<file_change path="codx/junior/file_patch/format.py" language="python" change_type="new" encoding="text">
"""``find-replace/1`` — the patch format used to change files without rewriting them.

Why a new format
----------------
Sending a whole file inside a ``<file_change>`` block costs a full read and a
full write, breaks on >1000 line files, and — worse — makes *partial* changes
impossible: the client assumed the payload was the whole file, so a truncated
payload produced a bogus diff that could not be applied.

A ``find-replace/1`` block instead carries *anchored* hunks::

    <file_change path="codx/junior/tools/__init__.py" change_type="patch" format="find-replace/1" sha256="...">
    <<<<<<< FIND
    from codx.junior.tools.browser_tools import browser_tools

    TOOLS = [
    =======
    from codx.junior.tools.browser_tools import browser_tools
    from codx.junior.tools.browser_script_registration import register_browser_script_tools

    TOOLS = [
    >>>>>>> REPLACE
    <file_change/>

Rules (deterministic, no heuristics that can silently corrupt a file)
--------------------------------------------------------------------
* ``FIND`` is the exact current text, indentation included. It must be
  **unique** in the file; add context lines to make it unique.
* ``at=<line>`` (optional) only breaks *ties between already verified*
  occurrences. It never bypasses verification.
* ``FIND`` may be empty-replaced (``=======`` followed by nothing) to delete a
  block; ``<<<<<<< CREATE`` creates a file, ``<<<<<<< DELETE`` removes it.
* ``SEARCH`` is accepted as a synonym of ``FIND`` (models know the Aider form).
* A line starting with a backslash escapes a marker line: ``\\=======``.
* Matching tries exact, then right-trimmed whitespace. Fuzzy matching is
  opt-in and always reported as ``match="fuzzy"`` so the user sees it in the
  approval diff. Indentation-insensitive matches are only used for
  *suggestions*, never applied — in Python that would change semantics.

All the functions here are pure (no filesystem, no FastAPI) so the same code
runs in the tool layer, in the API and in tests.
"""

from __future__ import annotations

import difflib
import hashlib
import re
from dataclasses import dataclass, field
from typing import Any, Dict, List, Optional, Tuple

FORMAT_NAME = "find-replace/1"
FUZZY_THRESHOLD = 0.90
MAX_FUZZY_WINDOWS = 3
MAX_REPORTED_CANDIDATES = 6

__all__ = [
    "FORMAT_NAME",
    "PatchError",
    "Hunk",
    "ChangeBlock",
    "LocatedHunk",
    "PatchProblem",
    "parse_change_block",
    "parse_attributes",
    "locate_hunks",
    "apply_hunks",
    "unified_diff",
    "split_lines",
    "join_lines",
    "sha256_text",
    "build_change_block",
]

# <<<<<<< FIND at=120   /  <<<<<<< SEARCH  /  <<<<<<< CREATE  /  <<<<<<< DELETE
_MARK_OPEN = re.compile(r"^<{7,}[ \t]*(FIND|SEARCH|CREATE|DELETE)\b(.*)$", re.IGNORECASE)
_MARK_SEP = re.compile(r"^={7,}[ \t]*$")
_MARK_CLOSE = re.compile(r"^>{7,}[ \t]*(REPLACE|CREATE|DELETE)\b.*$", re.IGNORECASE)
_ESCAPED = re.compile(r"^\\(<{7,}|={7,}|>{7,})(.*)$")
_ATTR = re.compile(r"([A-Za-z_][\w-]*)\s*=\s*(?:\"([^\"]*)\"|'([^']*)'|([^\s/>]+))")


class PatchError(Exception):
    """Raised when a patch cannot even be parsed (bad envelope, no hunks...)."""

    def __init__(self, code: str, message: str, **details: Any) -> None:
        super().__init__(message)
        self.code = code
        self.message = message
        self.details = details

    def to_dict(self) -> Dict[str, Any]:
        data: Dict[str, Any] = {"code": self.code, "message": self.message}
        data.update(self.details)
        return data


# --------------------------------------------------------------------------- #
# text helpers
# --------------------------------------------------------------------------- #
def sha256_text(text: str) -> str:
    return hashlib.sha256((text or "").encode("utf-8")).hexdigest()


def split_lines(text: str) -> Tuple[List[str], str, bool]:
    """Return ``(lines, newline, trailing_newline)`` without losing CRLF."""
    normalized = text or ""
    newline = "\r\n" if "\r\n" in normalized else "\n"
    normalized = normalized.replace("\r\n", "\n").replace("\r", "\n")
    if not normalized:
        return [], newline, False
    trailing = normalized.endswith("\n")
    lines = normalized.split("\n")
    if trailing:
        lines = lines[:-1]
    return lines, newline, trailing


def join_lines(lines: List[str], newline: str = "\n", trailing: bool = True) -> str:
    text = newline.join(lines)
    return f"{text}{newline}" if trailing and lines else text


def parse_attributes(text: str) -> Dict[str, str]:
    """Parse ``name="value" name2=value`` attribute soup."""
    attributes: Dict[str, str] = {}
    for match in _ATTR.finditer(text or ""):
        value = match.group(2)
        if value is None:
            value = match.group(3) if match.group(3) is not None else match.group(4)
        attributes[match.group(1).lower()] = value or ""
    return attributes


def _trim_blank_edges(text: str) -> str:
    lines = text.split("\n")
    while lines and not lines[0].strip():
        lines.pop(0)
    while lines and not lines[-1].strip():
        lines.pop()
    return "\n".join(lines)


def _unescape(line: str) -> str:
    match = _ESCAPED.match(line)
    return f"{match.group(1)}{match.group(2)}" if match else line


def _split(text: str) -> List[str]:
    return (text or "").replace("\r\n", "\n").replace("\r", "\n").split("\n")


def _is_open_envelope(line: str) -> bool:
    stripped = (line or "").strip().lower()
    return stripped.startswith("<file_change") and not stripped.startswith("</")


def _is_any_envelope(line: str) -> bool:
    stripped = (line or "").strip().lower()
    return stripped.startswith("<file_change") or stripped.startswith("</file_change")


def _human_lines(numbers: List[int]) -> str:
    return ", ".join(str(number) for number in numbers[:MAX_REPORTED_CANDIDATES])


# --------------------------------------------------------------------------- #
# model
# --------------------------------------------------------------------------- #
@dataclass
class Hunk:
    kind: str = "replace"  # replace | create | delete
    find: str = ""
    replace: str = ""
    hint_line: Optional[int] = None
    attributes: Dict[str, str] = field(default_factory=dict)

    @property
    def find_lines(self) -> List[str]:
        return self.find.split("\n") if self.find else []

    @property
    def replace_lines(self) -> List[str]:
        return self.replace.split("\n") if self.replace else []

    def to_dict(self) -> Dict[str, Any]:
        data: Dict[str, Any] = {"kind": self.kind, "find": self.find, "replace": self.replace}
        if self.hint_line:
            data["hint_line"] = self.hint_line
        return data


@dataclass
class ChangeBlock:
    path: Optional[str] = None
    attributes: Dict[str, str] = field(default_factory=dict)
    hunks: List[Hunk] = field(default_factory=list)

    @property
    def change_type(self) -> str:
        return (self.attributes.get("change_type") or ("patch" if self.hunks else "")).lower()

    @property
    def format(self) -> str:
        return self.attributes.get("format") or FORMAT_NAME

    @property
    def sha256(self) -> Optional[str]:
        return self.attributes.get("sha256") or self.attributes.get("expected_sha256")

    def to_dict(self) -> Dict[str, Any]:
        return {
            "path": self.path,
            "change_type": self.change_type,
            "format": self.format,
            "hunks": [hunk.to_dict() for hunk in self.hunks],
        }


@dataclass
class LocatedHunk:
    index: int
    hunk: Hunk
    start: int  # 0 based, inclusive
    end: int  # 0 based, exclusive
    match: str = "exact"

    def to_dict(self, total_lines: Optional[int] = None) -> Dict[str, Any]:
        data: Dict[str, Any] = {
            "index": self.index,
            "kind": self.hunk.kind,
            "status": "ok",
            "match": self.match,
            "start_line": self.start + 1,
            "end_line": max(self.end, self.start + 1),
            "find": self.hunk.find,
            "replace": self.hunk.replace,
            "line_map": {
                "old_start": self.start + 1,
                "old_count": self.end - self.start,
                "new_start": self.start + 1,
                "new_count": len(self.hunk.replace_lines),
            },
        }
        if total_lines is not None:
            data["total_lines"] = total_lines
        return data


@dataclass
class PatchProblem:
    code: str
    message: str
    hunk_index: Optional[int] = None
    candidates: List[Dict[str, Any]] = field(default_factory=list)

    def to_dict(self) -> Dict[str, Any]:
        data: Dict[str, Any] = {"code": self.code, "message": self.message}
        if self.hunk_index is not None:
            data["hunk_index"] = self.hunk_index
        if self.candidates:
            data["candidates"] = self.candidates
        return data


# --------------------------------------------------------------------------- #
# parsing
# --------------------------------------------------------------------------- #
def parse_change_block(text: str) -> ChangeBlock:
    """Parse a ``<file_change>`` envelope (or bare hunks) into a :class:`ChangeBlock`."""
    lines = _split(text)
    while lines and not lines[0].strip():
        lines.pop(0)
    while lines and not lines[-1].strip():
        lines.pop()

    attributes: Dict[str, str] = {}
    # Only the *edges* are treated as envelope, so a patch that legitimately
    # contains the literal "<file_change/>" (a docstring, a test fixture...)
    # is not corrupted.
    if lines and _is_open_envelope(lines[0]):
        attributes = parse_attributes(lines[0])
        lines = lines[1:]
    if lines and _is_any_envelope(lines[-1]):
        lines = lines[:-1]

    hunks = _parse_hunks(lines)
    path = attributes.get("path") or attributes.get("file") or attributes.get("file_path")
    return ChangeBlock(path=path, attributes=attributes, hunks=hunks)


def _parse_hunks(lines: List[str]) -> List[Hunk]:
    hunks: List[Hunk] = []
    index, total = 0, len(lines)
    while index < total:
        opening = _MARK_OPEN.match(lines[index])
        if not opening:
            index += 1
            continue
        marker = opening.group(1).upper()
        attributes = parse_attributes(opening.group(2))
        hint = attributes.get("at") or attributes.get("line")
        kind = "replace" if marker in ("FIND", "SEARCH") else marker.lower()
        start = index + 1
        index = start
        body: List[str] = []
        replacement: List[str] = []
        current = body
        closed = False
        while index < total:
            line = lines[index]
            if kind == "replace" and current is body and _MARK_SEP.match(line):
                current = replacement
                index += 1
                continue
            if _MARK_CLOSE.match(line):
                closed = True
                index += 1
                break
            current.append(_unescape(line))
            index += 1
        if not closed:
            raise PatchError(
                "unterminated_block",
                f"unterminated <<<<<<< {marker} block starting at line {start}",
                line=start,
            )
        hint_line = None
        if hint:
            try:
                hint_line = int(str(hint).strip())
            except (TypeError, ValueError):
                hint_line = None
        if kind == "delete":
            hunks.append(Hunk(kind="delete", attributes=attributes))
            continue
        if kind == "create":
            hunks.append(Hunk(kind="create", replace=_trim_blank_edges("\n".join(body)), attributes=attributes))
            continue
        find = _trim_blank_edges("\n".join(body))
        if not find:
            raise PatchError("empty_find", f"FIND block at line {start} is empty", line=start)
        hunks.append(
            Hunk(
                kind="replace",
                find=find,
                replace=_trim_blank_edges("\n".join(replacement)),
                hint_line=hint_line,
                attributes=attributes,
            )
        )
    if not hunks:
        if any(line.strip() for line in lines):
            raise PatchError(
                "no_hunks",
                "no <<<<<<< FIND ... ======= ... >>>>>>> REPLACE block found (a plain diff or a full "
                "file cannot be applied; send anchored hunks instead)",
            )
        raise PatchError("no_hunks", "the patch is empty")
    return hunks


# --------------------------------------------------------------------------- #
# locating
# --------------------------------------------------------------------------- #
def _positions(file_lines: List[str], find_lines: List[str], level: int) -> List[int]:
    length = len(find_lines)
    if not length or length > len(file_lines):
        return []

    def normalize(line: str) -> str:
        if level <= 0:
            return line
        if level == 1:
            return line.rstrip()
        return line.strip()

    target = [normalize(line) for line in find_lines]
    haystack = [normalize(line) for line in file_lines]
    head = target[0]
    found: List[int] = []
    for start in range(len(haystack) - length + 1):
        if haystack[start] != head:
            continue
        if haystack[start:start + length] == target:
            found.append(start)
    return found


def _pick_by_hint(starts: List[int], hint: Optional[int], length: int) -> Optional[int]:
    """Choose the occurrence closest to the ``at=`` hint (tie breaker only)."""
    if not hint or not starts:
        return None
    best = min(starts, key=lambda start: abs((start + 1) - hint))
    return best if abs((best + 1) - hint) <= max(length, 3) else None


def _candidate(file_lines: List[str], start: int, length: int) -> Dict[str, Any]:
    next_index = start + length
    return {
        "line": start + 1,
        "match": "\n".join(file_lines[start:next_index]),
        # Appending this line to the FIND block usually makes it unique.
        "next_line": file_lines[next_index] if next_index < len(file_lines) else None,
    }


def _best_windows(file_lines: List[str], find_lines: List[str], limit: int = MAX_FUZZY_WINDOWS) -> List[Tuple[int, float]]:
    """Similar windows, best first: used for fuzzy matching and for suggestions."""
    length = len(find_lines)
    if not length or length > len(file_lines):
        return []
    target = "\n".join(line.strip() for line in find_lines)
    scored: List[Tuple[float, int]] = []
    for start in range(len(file_lines) - length + 1):
        window = "\n".join(line.strip() for line in file_lines[start:start + length])
        ratio = difflib.SequenceMatcher(None, target, window).ratio()
        if ratio >= 0.60:
            scored.append((ratio, start))
    scored.sort(reverse=True)
    return [(start, ratio) for ratio, start in scored[:limit]]


def _locate_one(file_lines: List[str], hunk: Hunk, allow_fuzzy: bool):
    """Return ``(start, match_kind)`` or a :class:`PatchProblem`."""
    find_lines = hunk.find_lines
    length = len(find_lines)
    for level, label in ((0, "exact"), (1, "trimmed")):
        starts = _positions(file_lines, find_lines, level)
        if len(starts) == 1:
            return starts[0], label
        if len(starts) > 1:
            chosen = _pick_by_hint(starts, hunk.hint_line, length)
            if chosen is not None:
                return chosen, f"{label}+at"
            return PatchProblem(
                "ambiguous",
                f"FIND block matches {len(starts)} places (lines {_human_lines([s + 1 for s in starts])}); "
                "copy a neighbouring line into the FIND block to make it unique",
                candidates=[_candidate(file_lines, start, length) for start in starts[:MAX_REPORTED_CANDIDATES]],
            )

    windows = _best_windows(file_lines, find_lines)
    if allow_fuzzy and windows:
        accepted = [(start, ratio) for start, ratio in windows if ratio >= FUZZY_THRESHOLD]
        if len(accepted) == 1:
            return accepted[0][0], "fuzzy"
        if len(accepted) > 1:
            chosen = _pick_by_hint([start for start, _ in accepted], hunk.hint_line, length)
            if chosen is not None:
                return chosen, "fuzzy+at"
            return PatchProblem(
                "ambiguous",
                "fuzzy matching found several candidates; add context lines to the FIND block",
                candidates=[_candidate(file_lines, start, length) for start, _ in accepted],
            )

    problem = PatchProblem(
        "no_match",
        "FIND block not found in the current file: it must match the existing text exactly "
        "(indentation included). Re-read the region with `read_file_window` / `search_in_file`.",
    )
    if windows:
        problem.candidates = [_candidate(file_lines, start, length) for start, _ in windows]
    return problem


def locate_hunks(
    file_lines: List[str],
    hunks: List[Hunk],
    allow_fuzzy: bool = False,
) -> Tuple[List[LocatedHunk], List[PatchProblem]]:
    """Resolve every ``replace`` hunk against ``file_lines``.

    Returns the located hunks and the problems found. A patch with problems
    must not be applied.
    """
    located: List[LocatedHunk] = []
    problems: List[PatchProblem] = []

    for position, hunk in enumerate(hunks):
        if hunk.kind != "replace":
            continue
        outcome = _locate_one(file_lines, hunk, allow_fuzzy=allow_fuzzy)
        if isinstance(outcome, PatchProblem):
            outcome.hunk_index = position
            problems.append(outcome)
            continue
        start, match = outcome
        located.append(
            LocatedHunk(index=position, hunk=hunk, start=start, end=start + len(hunk.find_lines), match=match)
        )

    accepted: List[LocatedHunk] = []
    for item in sorted(located, key=lambda entry: item_start(entry)):
        if accepted and item.start < accepted[-1].end:
            problems.append(
                PatchProblem(
                    "overlap",
                    f"hunks #{accepted[-1].index} and #{item.index} overlap; merge them into one hunk",
                    hunk_index=item.index,
                )
            )
            continue
        accepted.append(item)

    return accepted, problems


def item_start(item: LocatedHunk) -> int:
    return item.start


# --------------------------------------------------------------------------- #
# applying
# --------------------------------------------------------------------------- #
def apply_hunks(file_lines: List[str], located: List[LocatedHunk]) -> List[str]:
    """Apply located hunks bottom-up so earlier offsets stay valid."""
    result = list(file_lines)
    for item in sorted(located, key=lambda entry: entry.start, reverse=True):
        result[item.start:item.end] = item.hunk.replace_lines
    return result


def unified_diff(path: str, original: str, new: str, context: int = 3) -> str:
    original_lines, _, _ = split_lines(original)
    new_lines, _, _ = split_lines(new)
    diff = difflib.unified_diff(
        original_lines,
        new_lines,
        fromfile=f"a/{path}",
        tofile=f"b/{path}",
        n=max(int(context or 0), 0),
        lineterm="",
    )
    return "\n".join(diff)


# --------------------------------------------------------------------------- #
# rendering
# --------------------------------------------------------------------------- #
def _escape_attribute(value: str) -> str:
    return str(value).replace('"', "'")


def build_change_block(
    path: str,
    hunks: List[Hunk],
    sha256: Optional[str] = None,
    extra_attributes: Optional[Dict[str, str]] = None,
) -> str:
    """Render the canonical block the chat UI parses (round-trips through the parser)."""
    attributes: Dict[str, str] = {"path": path, "change_type": "patch", "format": FORMAT_NAME}
    if sha256:
        attributes["sha256"] = sha256
    if extra_attributes:
        attributes.update({key: value for key, value in extra_attributes.items() if value})
    header = " ".join(f'{key}="{_escape_attribute(value)}"' for key, value in attributes.items())
    lines = [f"<file_change {header}>"]
    for hunk in hunks:
        marker = {"replace": "FIND", "create": "CREATE", "delete": "DELETE"}.get(hunk.kind, "FIND")
        opening = f"<<<<<<< {marker}"
        if hunk.hint_line:
            opening += f" at={hunk.hint_line}"
        lines.append(opening)
        if hunk.kind == "replace":
            lines.extend(hunk.find_lines)
            lines.append("=======")
            lines.extend(hunk.replace_lines)
        elif hunk.kind == "create":
            lines.extend(hunk.replace_lines)
        lines.append(f">>>>>>> {'REPLACE' if hunk.kind == 'replace' else marker}")
    lines.append("<file_change/>")
    return "\n".join(lines)
