"""Filesystem side of ``find-replace/1``: read, validate, diff, apply.

Everything the API and the tools need lives here so both stay thin and agree
on the same rules:

* paths are resolved **inside the project** (no escaping, no ``.git``);
* the file is read once, the patch is located against *that* content, and the
  diff is computed from ``new_content = apply(original, hunks)`` — the diff can
  therefore never disagree with what will be written;
* ``sha256`` of the validated content is returned and required on apply
  (optimistic concurrency: a file edited meanwhile is rejected, not clobbered);
* every apply leaves ``.codx/patches/<ts>-<name>.bak`` plus the ``.patch`` text.
"""

from __future__ import annotations

import logging
import os
import re
import tempfile
from dataclasses import dataclass, field
from datetime import datetime, timezone
from typing import Any, Dict, List, Optional

from codx.junior.file_patch.format import (
    FORMAT_NAME,
    Hunk,
    PatchError,
    apply_hunks,
    join_lines,
    locate_hunks,
    parse_change_block,
    sha256_text,
    split_lines,
    unified_diff,
)

logger = logging.getLogger(__name__)

BACKUP_DIRNAME = os.path.join(".codx", "patches")
MAX_FILE_BYTES = 4 * 1024 * 1024
PROTECTED_PARTS = (".git", "node_modules", "__pycache__", ".venv", "venv")

__all__ = [
    "PatchResult",
    "resolve_project_path",
    "resolve_path",
    "read_text",
    "write_text",
    "validate_patch",
    "apply_patch",
    "read_window",
    "search_in_file",
]


# --------------------------------------------------------------------------- #
# project / path resolution
# --------------------------------------------------------------------------- #
def resolve_project_path(project_id: Optional[str] = None, project_path: Optional[str] = None) -> str:
    """Resolve the project folder: explicit path → settings → env → cwd.

    Single adapter point shared by the API and the tools (a tool call may come
    from a chat session that only knows its ``project_id``).
    """
    if project_path:
        return os.path.abspath(os.path.expanduser(str(project_path)))

    try:  # pragma: no cover - settings are optional in unit tests
        from codx.junior.settings import CODXJuniorSettings

        if project_id:
            try:
                return CODXJuniorSettings.from_project_id(project_id).project_path
            except Exception:
                logger.debug("Could not resolve project_id %s", project_id, exc_info=True)
        return CODXJuniorSettings().project_path
    except Exception:
        logger.debug("CODXJuniorSettings not available", exc_info=True)

    for key in ("CODX_PROJECT_PATH", "CODX_JUNIOR_PROJECT_PATH", "PROJECT_PATH"):
        value = os.environ.get(key)
        if value:
            return os.path.abspath(os.path.expanduser(value))
    return os.getcwd()


def resolve_path(project_path: str, file_path: str) -> str:
    """Absolute path of ``file_path`` inside ``project_path`` or :class:`PatchError`."""
    project_root = os.path.abspath(project_path or ".")
    raw = str(file_path or "").strip()
    if not raw:
        raise PatchError("missing_path", "file_path is required")
    candidate = raw if os.path.isabs(raw) else os.path.join(project_root, raw)
    resolved = os.path.abspath(candidate)
    try:
        inside = os.path.commonpath([project_root, resolved]) == project_root
    except ValueError:  # different drives on Windows
        inside = False
    if not inside:
        raise PatchError("outside_project", f"{raw} is outside the project folder")
    relative = os.path.relpath(resolved, project_root)
    for part in relative.split(os.sep):
        if part in PROTECTED_PARTS:
            raise PatchError("protected_path", f"{relative} is inside a protected folder ({part})")
    return resolved


def relative_path(project_path: str, absolute: str) -> str:
    return os.path.relpath(absolute, os.path.abspath(project_path or ".")).replace(os.sep, "/")


# --------------------------------------------------------------------------- #
# io
# --------------------------------------------------------------------------- #
def read_text(path: str) -> str:
    if not os.path.isfile(path):
        return ""
    size = os.path.getsize(path)
    if size > MAX_FILE_BYTES:
        raise PatchError("file_too_large", f"{path} is bigger than {MAX_FILE_BYTES // (1024 * 1024)}MB")
    with open(path, "rb") as handler:
        raw = handler.read()
    if b"\x00" in raw:
        raise PatchError("binary_file", f"{path} looks binary")
    try:
        return raw.decode("utf-8")
    except UnicodeDecodeError as error:
        raise PatchError("encoding", f"{path} is not UTF-8: {error}") from error


def write_text(path: str, content: str) -> None:
    """Atomic write that keeps the previous file mode."""
    folder = os.path.dirname(os.path.abspath(path)) or "."
    os.makedirs(folder, exist_ok=True)
    mode = os.stat(path).st_mode if os.path.isfile(path) else None
    descriptor, tmp_path = tempfile.mkstemp(dir=folder, prefix=".tmp-", suffix=os.path.basename(path))
    try:
        with os.fdopen(descriptor, "w", encoding="utf-8", newline="") as handler:
            handler.write(content)
            handler.flush()
            os.fsync(handler.fileno())
        if mode is not None:
            os.chmod(tmp_path, mode)
        os.replace(tmp_path, path)
    finally:
        if os.path.exists(tmp_path):
            try:
                os.remove(tmp_path)
            except OSError:
                pass


# --------------------------------------------------------------------------- #
# result
# --------------------------------------------------------------------------- #
@dataclass
class PatchResult:
    path: str = ""
    ok: bool = False
    exists: bool = False
    sha256: str = ""
    format: str = FORMAT_NAME
    hunks: List[Dict[str, Any]] = field(default_factory=list)
    problems: List[Dict[str, Any]] = field(default_factory=list)
    unified_diff: str = ""
    original_content: str = ""
    new_content: str = ""
    stats: Dict[str, int] = field(default_factory=dict)
    backup_path: Optional[str] = None

    def to_dict(self, include_content: bool = True) -> Dict[str, Any]:
        data: Dict[str, Any] = {
            "ok": self.ok,
            "path": self.path,
            "exists": self.exists,
            "sha256": self.sha256,
            "format": self.format,
            "hunks": self.hunks,
            "problems": self.problems,
            "unified_diff": self.unified_diff,
            "stats": self.stats,
        }
        if self.backup_path:
            data["backup_path"] = self.backup_path
        if include_content:
            lines, _, _ = split_lines(self.original_content)
            data["original_content"] = self.original_content
            data["new_content"] = self.new_content
            data["total_lines"] = len(lines)
        return data


def _diff_stats(diff: str) -> Dict[str, int]:
    added = removed = 0
    for line in (diff or "").split("\n"):
        if line.startswith("+++") or line.startswith("---"):
            continue
        if line.startswith("+"):
            added += 1
        elif line.startswith("-"):
            removed += 1
    return {"added_lines": added, "removed_lines": removed}


# --------------------------------------------------------------------------- #
# validate
# --------------------------------------------------------------------------- #
def validate_patch(
    project_path: str,
    file_path: Optional[str],
    patch: str,
    allow_fuzzy: bool = False,
    context: int = 3,
    include_content: bool = True,
) -> PatchResult:
    """Resolve ``patch`` against the current file and build the real diff.

    Never writes. ``file_path`` may be omitted when the block carries ``path=``.
    """
    block = parse_change_block(patch)
    target = file_path or block.path
    if not target:
        raise PatchError("missing_path", "file_path is required (or set path= on the <file_change> block)")

    absolute = resolve_path(project_path, target)
    relative = relative_path(project_path, absolute)
    exists = os.path.isfile(absolute)
    original = read_text(absolute) if exists else ""
    result = PatchResult(
        path=relative,
        exists=exists,
        sha256=sha256_text(original),
        original_content=original,
    )

    creates = [hunk for hunk in block.hunks if hunk.kind == "create"]
    deletes = [hunk for hunk in block.hunks if hunk.kind == "delete"]
    replacements = [hunk for hunk in block.hunks if hunk.kind == "replace"]

    if creates and (deletes or replacements):
        result.problems.append(
            {"code": "conflicting_hunks", "message": "a CREATE block cannot be combined with other blocks"}
        )
        return result
    if len(creates) > 1 or len(deletes) > 1:
        result.problems.append(
            {"code": "conflicting_hunks", "message": "only one CREATE or DELETE block per file is allowed"}
        )
        return result

    if creates:
        if exists and original.strip():
            result.problems.append(
                {
                    "code": "already_exists",
                    "message": f"{relative} already exists: send FIND/REPLACE hunks instead of a CREATE block",
                }
            )
            return result
        content = creates[0].replace
        new_content = f"{content}\n" if content and not content.endswith("\n") else content
        result.hunks.append(
            {
                "index": 0,
                "kind": "create",
                "status": "ok",
                "match": "create",
                "start_line": 1,
                "end_line": 0,
                "find": "",
                "replace": creates[0].replace,
            }
        )
    elif deletes:
        if not exists:
            result.problems.append({"code": "missing_file", "message": f"{relative} does not exist"})
            return result
        new_content = ""
        result.hunks.append(
            {
                "index": 0,
                "kind": "delete",
                "status": "ok",
                "match": "delete",
                "start_line": 1,
                "end_line": 0,
                "find": "",
                "replace": "",
            }
        )
    else:
        if not exists:
            result.problems.append(
                {"code": "missing_file", "message": f"{relative} does not exist: use a CREATE block to add it"}
            )
            return result
        file_lines, newline, trailing = split_lines(original)
        located, problems = locate_hunks(file_lines, replacements, allow_fuzzy=allow_fuzzy)
        result.problems.extend(problem.to_dict() for problem in problems)
        if problems:
            result.hunks = [item.to_dict(len(file_lines)) for item in located]
            return result
        new_content = join_lines(apply_hunks(file_lines, located), newline=newline, trailing=trailing)
        total = len(file_lines)
        result.hunks = [item.to_dict(total) for item in sorted(located, key=lambda entry: entry.index)]

    result.new_content = new_content
    result.unified_diff = unified_diff(result.path, original, new_content, context=context)
    result.stats = _diff_stats(result.unified_diff)
    if new_content == original:
        result.problems.append({"code": "no_change", "message": "the patch does not change the file"})
        return result
    result.ok = not result.problems
    return result


# --------------------------------------------------------------------------- #
# apply
# --------------------------------------------------------------------------- #
def _write_backup(project_path: str, absolute: str, patch: str, original: str) -> str:
    folder = os.path.join(os.path.abspath(project_path), BACKUP_DIRNAME)
    os.makedirs(folder, exist_ok=True)
    stamp = datetime.now(timezone.utc).strftime("%Y%m%d-%H%M%S")
    name = f"{stamp}-{os.path.basename(absolute)}"
    bak = os.path.join(folder, f"{name}.bak")
    if original:
        write_text(bak, original)
    write_text(os.path.join(folder, f"{name}.patch"), patch)
    return relative_path(project_path, bak)


def apply_patch(
    project_path: str,
    file_path: Optional[str],
    patch: str,
    expected_sha256: Optional[str] = None,
    allow_fuzzy: bool = False,
    backup: bool = True,
    context: int = 3,
) -> PatchResult:
    """Validate then write (atomically, with a backup). Safe to call twice."""
    result = validate_patch(
        project_path,
        file_path,
        patch,
        allow_fuzzy=allow_fuzzy,
        context=context,
    )
    if expected_sha256 and result.sha256 != expected_sha256:
        result.ok = False
        result.problems.append(
            {
                "code": "stale_file",
                "message": "the file changed since the patch was validated; re-read it and regenerate the patch",
            }
        )
        return result
    if not result.ok:
        return result

    absolute = resolve_path(project_path, result.path)
    if backup:
        result.backup_path = _write_backup(project_path, absolute, patch, result.original_content)
    if result.hunks and result.hunks[0].get("kind") == "delete":
        os.remove(absolute)
    else:
        write_text(absolute, result.new_content)
    logger.info("Applied find-replace patch to %s (%s hunks)", result.path, len(result.hunks))
    return result


# --------------------------------------------------------------------------- #
# read helpers (used by the tools so a model never loads a whole big file)
# --------------------------------------------------------------------------- #
def read_window(
    project_path: str,
    file_path: str,
    start: int = 1,
    end: Optional[int] = None,
    max_lines: int = 200,
) -> Dict[str, Any]:
    absolute = resolve_path(project_path, file_path)
    lines, _, _ = split_lines(read_text(absolute))
    total = len(lines)
    first = max(1, int(start or 1))
    last = total if end is None else int(end)
    last = min(last, first + max(int(max_lines or 200), 1) - 1, total)
    window = [{"line": number + 1, "text": lines[number]} for number in range(first - 1, last)]
    return {
        "path": relative_path(project_path, absolute),
        "total_lines": total,
        "start": first,
        "end": last,
        "lines": window,
        "has_more": last < total,
    }


def search_in_file(
    project_path: str,
    file_path: str,
    pattern: str,
    context: int = 2,
    max_results: int = 20,
    regex: bool = True,
    ignore_case: bool = True,
) -> Dict[str, Any]:
    absolute = resolve_path(project_path, file_path)
    lines, _, _ = split_lines(read_text(absolute))
    flags = re.IGNORECASE if ignore_case else 0
    try:
        matcher = re.compile(pattern if regex else re.escape(pattern), flags)
    except re.error as error:
        raise PatchError("bad_pattern", f"invalid regular expression: {error}") from error

    matches: List[Dict[str, Any]] = []
    for index, line in enumerate(lines):
        if not matcher.search(line):
            continue
        first = max(0, index - max(int(context or 0), 0))
        last = min(len(lines), index + max(int(context or 0), 0) + 1)
        matches.append(
            {
                "line": index + 1,
                "text": line,
                # Ready to paste as a FIND block: exact lines, exact indentation.
                "find_snippet": "\n".join(lines[first:last]),
                "before": "\n".join(lines[first:index]),
                "after": "\n".join(lines[index + 1:last]),
            }
        )
        if len(matches) >= max(int(max_results or 20), 1):
            break
    return {
        "path": relative_path(project_path, absolute),
        "total_lines": len(lines),
        "matches": matches,
        "truncated": len(matches) >= max(int(max_results or 20), 1),
    }
