"""Generic helpers to plug tool entries into the codx-junior tool registry.

The registry lives in ``codx/junior/tools/__init__.py`` and is huge; tool
modules should therefore never edit it, only append to it through these
helpers. Both shapes are supported because the codebase uses lists of
``{tool_json, settings, tags, tool_call}`` entries and ``name -> entry`` maps.

Registration is idempotent and tolerant: an unknown registry type logs a
warning and is returned untouched instead of breaking a profile build.
"""

from __future__ import annotations

import logging
from typing import Any, Iterable, List, Optional, Sequence

logger = logging.getLogger(__name__)

__all__ = [
    "tool_name",
    "tool_names",
    "missing_entries",
    "register_tool_entries",
    "ensure_registered",
]


def tool_name(entry: Any) -> Optional[str]:
    """Return the function name of a registry entry (or ``None``)."""
    if isinstance(entry, str):
        return entry
    if not isinstance(entry, dict):
        return None
    tool_json = entry.get("tool_json", entry)
    if isinstance(tool_json, dict):
        function = tool_json.get("function")
        if isinstance(function, dict) and function.get("name"):
            return str(function["name"])
        if tool_json.get("name"):
            return str(tool_json["name"])
    if entry.get("name"):
        return str(entry["name"])
    return None


def tool_names(registry: Any) -> List[str]:
    if isinstance(registry, dict):
        entries: Iterable[Any] = registry.values()
    elif isinstance(registry, (list, tuple, set)):
        entries = registry
    else:
        return []
    return [name for name in (tool_name(entry) for entry in entries) if name]


def missing_entries(registry: Any, entries: Sequence[dict]) -> List[dict]:
    present = set(tool_names(registry))
    return [entry for entry in entries if tool_name(entry) not in present]


def register_tool_entries(registry: Any, entries: Sequence[dict]) -> Any:
    """Add ``entries`` to ``registry`` (list append / dict setdefault)."""
    if registry is None:
        logger.warning("register_tool_entries called with a None registry")
        return registry
    if isinstance(registry, list):
        for entry in missing_entries(registry, entries):
            registry.append(entry)
        return registry
    if isinstance(registry, dict):
        for entry in entries:
            name = tool_name(entry)
            if name and name not in registry:
                registry[name] = entry
        return registry
    logger.warning(
        "Unsupported tool registry type %s: entries not registered",
        type(registry).__name__,
    )
    return registry


def ensure_registered(entries: Sequence[dict], attribute: str = "TOOLS") -> List[str]:
    """Register into ``codx.junior.tools.<attribute>`` lazily (no import cycle)."""
    try:  # pragma: no cover - depends on the surrounding package
        from codx.junior import tools as tools_module
    except Exception:
        logger.debug("codx.junior.tools not importable", exc_info=True)
        return []
    registry = getattr(tools_module, attribute, None)
    if registry is None:
        logger.debug("codx.junior.tools has no %s registry", attribute)
        return []
    pending = missing_entries(registry, entries)
    if not pending:
        return []
    register_tool_entries(registry, entries)
    names = [tool_name(entry) or "?" for entry in pending]
    logger.info("Registered tools: %s", ", ".join(names))
    return names
